import { NivelGobiernoValue } from '../shared/models/tramite.model';

export type UserRole = 'inversor' | 'ejecutivo' | 'admin';

export interface User {
  id: number;
  name: string;
  email: string;
  email_verified_at: string | null;
  role: UserRole;
  nivelGobierno?: NivelGobiernoValue | null;
  nivel_gobierno?: NivelGobiernoValue | null;
  municipio?: string | null;
  personalidad_juridica?: 'fisica' | 'moral' | null;
  rfc?: string | null;
  nombre_completo?: string | null;
  denominacion_razon_social?: string | null;
  nombre_representante?: string | null;
  correo_notificaciones?: string | null;
  telefono?: string | null;
  calle?: string | null;
  numero_exterior?: string | null;
  numero_interior?: string | null;
  colonia?: string | null;
  codigo_postal?: string | null;
  clave_catastral?: string | null;
  superficie_total_m2?: number | null;
  superficie_construida_m2?: number | null;
  latitud?: number | null;
  longitud?: number | null;
  altitud?: number | null;
  actividad_principal?: string | null;
  descripcion_proyecto?: string | null;
  vida_util_anos?: number | null;
  created_at?: string;
}

export function roleLabel(role: UserRole): string {
  switch (role) {
    case 'inversor':
      return 'Inversor';
    case 'ejecutivo':
      return 'Ejecutivo';
    case 'admin':
      return 'Administrador';
  }
}
